// Procedimiento de Collatz: si n es par, dividilo por 2; si es impar, multiplicalo por 3 y sumale 1.
// Se repite hasta llegar a 1. Nadie sabe si termina para todo n positivo.
function pasosCollatz(n) {
  let pasos = 0;
  while (n !== 1) {
    n = n % 2 === 0 ? n / 2 : 3 * n + 1;
    pasos++;
  }
  return pasos;
}
for (const n of [6, 7, 19, 27, 97]) console.log(`n = ${n}: llega a 1 en ${pasosCollatz(n)} pasos`);

// Algoritmo: máximo de una lista. Precondición: la lista no está vacía.
function maximo(lista) {
  let mayor = lista[0];                      // arranca con el primer elemento
  console.log(`empiezo con mayor = ${mayor}`);
  for (let i = 1; i < lista.length; i++) {   // mira cada uno de los demás, una sola vez
    const x = lista[i];
    if (x > mayor) {
      mayor = x;
      console.log(`  ${x} le gana a lo que había: mayor = ${mayor}`);
    } else {
      console.log(`  ${x} no supera a ${mayor}: no cambia`);
    }
  }
  return mayor;
}

// Variante con un error de inicialización: arranca en 0 en lugar de en el primer elemento
function maximoMalo(lista) {
  let mayor = 0;
  for (const x of lista) if (x > mayor) mayor = x;
  return mayor;
}

console.log("resultado:", maximo([7, 3, 9, 4]));
console.log("---");
const saldos = [-5, -2, -9];                 // todos negativos
console.log("correcto:", maximo(saldos));
console.log("variante con error:", maximoMalo(saldos));
console.log("---");
console.log("lista vacía (viola la precondición):", maximo([]));

// Algoritmo de Euclides: máximo común divisor de dos enteros no negativos (no ambos cero)
function euclides(a, b, traza = true) {
  if (traza) console.log(`mcd(${a}, ${b})`);
  let pasos = 0;
  while (b !== 0) {
    const resto = a % b;                      // el resto de dividir a por b
    if (traza) console.log(`  ${a} = ${Math.floor(a / b)} × ${b} + ${resto}`);
    a = b;                                    // lo que era b pasa a ser a...
    b = resto;                                // ...y el resto pasa a ser b
    pasos++;
  }
  if (traza) console.log(`  b llegó a 0: el resultado es ${a} (${pasos} pasos)`);
  return traza ? a : { mcd: a, pasos };
}

euclides(3009, 884);
euclides(84, 60);
euclides(17, 5);

// Comprobación por fuerza bruta: probar todos los divisores posibles
function mcdBruto(a, b) {
  for (let d = Math.min(a, b); d >= 1; d--) if (a % d === 0 && b % d === 0) return d;
}
let coinciden = 0, total = 0;
for (let a = 1; a <= 200; a++) for (let b = 1; b <= 200; b++) {
  total++;
  if (euclides(a, b, false).mcd === mcdBruto(a, b)) coinciden++;
}
console.log(`comparación con fuerza bruta: coinciden ${coinciden} de ${total} pares (1 a 200)`);

// ¿Cuántos pasos necesita como máximo?
let peor = { pasos: 0 };
for (let a = 1; a <= 1000; a++) for (let b = 1; b <= a; b++) {
  const r = euclides(a, b, false);
  if (r.pasos > peor.pasos) peor = { a, b, pasos: r.pasos };
}
console.log(`con números hasta 1000, el peor caso es mcd(${peor.a}, ${peor.b}): ${peor.pasos} pasos`);

// Regla inventada para este día: «atender primero la parada que cierra antes».
// Minutos de viaje (iguales de ida y de vuelta) y hora límite de cada parada, en minutos desde la salida (09:00).
const viaje = {
  "A-D": 50, "B-D": 10, "C-D": 30,   // D = depósito
  "A-B": 45, "A-C": 20, "B-C": 15,
};
const limite = { A: 60, B: 65, C: 120 };            // A cierra 10:00, B 10:05, C 11:00
const t = (x, y) => viaje[[x, y].sort().join("-")];

function evaluar(orden) {
  let reloj = 0, actual = "D", tarde = 0;
  const partes = [];
  for (const p of orden) {
    reloj += t(actual, p);
    const ok = reloj <= limite[p];
    if (!ok) tarde++;
    partes.push(`${p} a los ${reloj} min ${ok ? "(a tiempo)" : "(TARDE por " + (reloj - limite[p]) + ")"}`);
    actual = p;
  }
  return { texto: partes.join(", ") + ` | total ${reloj} min`, tarde, total: reloj };
}

// La regla: ordenar por hora límite (si empatan, el más cercano al depósito)
const porRegla = Object.keys(limite).sort((x, y) => limite[x] - limite[y] || t("D", x) - t("D", y));
console.log("La regla elige", porRegla.join(" → "));
console.log("  ", evaluar(porRegla).texto);

// Fuerza bruta: probar todos los órdenes posibles
function permutaciones(a) {
  if (a.length <= 1) return [a];
  return a.flatMap((x, i) => permutaciones([...a.slice(0, i), ...a.slice(i + 1)]).map(r => [x, ...r]));
}
const todos = permutaciones(Object.keys(limite));
let minimo = Infinity;
console.log(`Hay ${todos.length} órdenes posibles. Los que llegan a tiempo a todas las paradas:`);
for (const o of todos) {
  const r = evaluar(o);
  if (r.tarde === 0) console.log("  ", o.join(" → "), "|", r.texto);
  minimo = Math.min(minimo, r.total);
}
console.log("El recorrido más corto de todos, sin mirar las horas límite, dura", minimo, "min");

// Modelo simplificado (mío) de `anotar` en src/estado/repaso.ts: qué caja le toca a una pregunta.
const INTERVALOS = [1, 1, 3, 7, 16, 35];   // días de espera según la caja (los mismos valores del código de Senda)

function anotar(tarjeta, acierto, enRepaso) {
  let caja;
  if (!acierto) caja = 0;                                  // fallar: vuelve a la caja 0
  else if (!tarjeta) caja = enRepaso ? 1 : 2;              // primera vez que se contesta
  else caja = Math.min(5, tarjeta.caja + 1);               // acertar: sube una caja, hasta la 5
  return { caja, espera: INTERVALOS[caja] };
}

let tarjeta = null;
const historia = [
  [true, false], [true, true], [true, true], [false, true],
  [true, true], [true, true], [true, true], [true, true],
];
historia.forEach(([acierto, enRepaso], i) => {
  tarjeta = anotar(tarjeta, acierto, enRepaso);
  console.log(`respuesta ${i + 1}: ${acierto ? "acierta" : "falla  "} -> caja ${tarjeta.caja}, vuelve en ${tarjeta.espera} día(s)`);
});
